const dateAdd=(v,n)=>{const d=new Date(v+'T12:00:00');d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const state=()=>data?.state;
const allPlans=()=>{const m=new Map();for(const p of [...(state()?.history||[]),...(state()?.plan?[state().plan]:[])])m.set(p.week,p);return [...m.values()]};
const allSessions=()=>allPlans().flatMap(p=>p.sessions);
const sessionBy=id=>allSessions().find(s=>s.id===id)||state()?.upcoming?.sessions.find(s=>s.id===id)||state()?.history?.slice().reverse().flatMap(p=>p.sessions).find(s=>s.id===id)||(previewAccountId===data?.user?.id?previewSessions.get(id):null);
const recordFor=s=>state().records.find(r=>r.session_id===s?.id);
const activityNames={walking:'步行 / 快走',strength:'力量训练',running:'跑步',cycling:'骑行',mobility:'拉伸 / 灵活性',badminton:'羽毛球（可约场或同伴）',dance:'有氧舞蹈',swimming:'游泳',hiking:'徒步',rowing:'划船',hiit:'间歇训练',yoga:'瑜伽',pilates:'普拉提',other:'其他运动'};
const kindNames={rest:'休息',walk:'步行 / 快走',indoor:'室内有氧',strength:'力量训练',run:'跑步',bike:'骑行',mobility:'拉伸与灵活性',badminton:'羽毛球',dance:'有氧舞蹈',sport:'专项运动'};
const periodNames={normal:'照常训练',ease:'减量训练',rest:'休息恢复'};
const periodButton=()=>state().profile?.sex==='female'&&!state().blocked?`<button class="text-btn small-text" data-action="period">${state().period?'经期调整 · '+periodNames[state().period.mode]:'经期运动调整'}</button>`:'';
const iconFor=s=>s?.kind==='strength'?'strength':s?.kind==='rest'?'leaf':'walk';
const isDone=s=>['completed','partial'].includes(recordFor(s)?.status);
const focusSession=()=>allSessions().find(s=>s.date===data.today);
function art(){return `<svg class="hero-art" viewBox="0 0 330 300" fill="none" aria-hidden="true"><defs><linearGradient id="hill" x1="130" y1="75" x2="250" y2="280" gradientUnits="userSpaceOnUse"><stop stop-color="#d8e5bc"/><stop offset="1" stop-color="#b5cc8b"/></linearGradient></defs><circle cx="213" cy="86" r="53" fill="#e1eacb"/><circle cx="213" cy="86" r="34" stroke="#d3dfba"/><path d="M-8 264C74 168 110 210 166 133C225 52 293 117 350 67V310H-8Z" fill="url(#hill)"/><path d="M76 303c45-63 77-42 106-87s19-72 61-87 63-10 96-40" stroke="#edf3df" stroke-width="21"/><path d="M76 303c45-63 77-42 106-87s19-72 61-87 63-10 96-40" stroke="#c7d7ad" stroke-dasharray="4 6"/><path d="M292 270c-18-33-8-46 5-63m-4 39-18-12m19-1 17-15M54 249c-8-19-1-28 8-35" stroke="#8da667" stroke-width="2" stroke-linecap="round"/><ellipse cx="197" cy="231" rx="32" ry="6" fill="#6d8659" opacity=".12"/><path d="m197 151-11 37-22 32m24-33 25 17 13 24" stroke="#344c35" stroke-width="10" stroke-linecap="round" stroke-linejoin="round"/><path d="m190 126 18 9-11 30-19-7Z" fill="#f6f8ed"/><path d="m192 135-17 15-18-6m43-6 13 18 17-5" stroke="#b38c68" stroke-width="6" stroke-linecap="round"/><circle cx="202" cy="116" r="11" fill="#b38c68"/><path d="M190 115c-4-17 19-23 23-7l-12 1-5 9Z" fill="#344c35"/><path d="m158 222 9 2m57 5 10 1" stroke="#506443" stroke-width="6" stroke-linecap="round"/><path d="M272 170v-34m-12 17 12-22 12 22Z" stroke="#6d8952" stroke-width="2"/><path d="M111 210v-23m-9 12 9-17 9 17Z" stroke="#91a974" stroke-width="2"/></svg>`}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('visible'),4200)}
async function api(path,method='GET',body){const res=await fetch('/api'+path,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const out=await res.json().catch(()=>({detail:'服务暂时不可用'}));if(!res.ok){if(res.status===409){await load();}const error=new Error(typeof out.detail==='string'?out.detail:'请检查填写的内容和范围');error.status=res.status;throw error}return out}
async function mutate(path,body={},method='POST'){const out=await api(path,method,{revision:data.revision,...body});if(out.state){data=out;render();}return out}
function planningKey(){return data?.user?.id?'sportswise-planning:'+data.user.id:null}
function savePlanning(){try{const key=planningKey();if(key&&planningJob)localStorage.setItem(key,JSON.stringify(planningJob))}catch{}}
function restorePlanning(){
 const accountId=data?.user?.id;if(!accountId)return;
 const fresh=planningSnapshot!==data;planningSnapshot=data;
 if(fresh&&Object.prototype.hasOwnProperty.call(data,'planning_job')){
  if(planningPollTimer)clearTimeout(planningPollTimer);
  planningJob=data.planning_job?{...data.planning_job,accountId}:null;
  if(planningJob){savePlanning();if(planningActive(planningJob))planningPollTimer=setTimeout(()=>pollPlanning(planningJob.id),0)}
  else{try{localStorage.removeItem(planningKey())}catch{}}
  return;
 }
 if(planningJob?.accountId===accountId)return;
 if(planningPollTimer)clearTimeout(planningPollTimer);planningJob=null;
 try{const saved=JSON.parse(localStorage.getItem(planningKey())||'null');if(saved?.accountId===accountId&&saved.id)planningJob=saved}catch{}
 if(planningActive(planningJob))planningPollTimer=setTimeout(()=>pollPlanning(planningJob.id),0);
}
function estimateText(e){if(!e)return '正在估算等待时间';const lo=Math.max(1,Number(e.min_seconds)||1),hi=Math.max(lo,Number(e.max_seconds)||lo);const range=hi<90?`${Math.floor(lo/10)*10||1}–${Math.ceil(hi/10)*10} 秒`:`${Math.max(1,Math.floor(lo/60))}–${Math.ceil(hi/60)} 分钟`;return `预计约 ${range}${e.queue_included?'（含排队）':''}；${e.basis==='history'?'按近期同类任务估计':'初步估计，样本仍在积累'}`}
function planningTime(job=planningJob){if(!planningActive(job))return '';const elapsed=Math.max(0,Math.floor(job.elapsed_seconds||0)),used=elapsed<60?`${elapsed} 秒`:`${Math.floor(elapsed/60)} 分 ${elapsed%60} 秒`;return `<p class="small-text muted planning-time">${esc(estimateText(job.estimate))} · 已用 ${used}。${job.over_estimate?'已超过预估，仍在处理；可以稍后回来查看。':''}${job.estimate_extension?esc(job.estimate_extension):''}</p>`}
function planningBanner(){if(!planningJob||planningJob.accountId!==data?.user?.id)return '';const done=planningJob.status==='done',failed=planningJob.status==='failed';return `<section id="planning-banner" class="card section" aria-live="polite"><div class="card-header"><h2>${done?'新计划已生成':failed?'这次计划未能完成':'正在为你生成计划'}</h2>${I('spark')}</div><p>${esc(planningJob.message||planningJob.error||'后台任务已启动。')}${done?' 请先检查具体课程，再决定是否采用。':''}</p>${planningTime()}<button class="btn ghost" data-action="planning-progress">${done?'查看计划草案':failed?'查看原因':'查看当前阶段'} ${I('arrow')}</button></section>`}
function planningStage(value){return ({revision_full_fallback:'完整修订稿复核',revision_patch:'按评审定点修订',agent_revision:'独立训练 agent 修订',normalization:'同步时长与已知强度',seed_reused:'复用草案并重新评审',analyse:'正在分析训练档案',rechecking:'正在重新检查草案',analyze:'正在分析训练档案',done:'计划草案已完成',structure:'课程结构与约束检查',independent_review:'独立评价进行中',queued:'任务已排队',generating:'AI 正在生成课程',generation:'AI 正在生成课程',reviewing:'独立评价进行中',independent_review:'独立评价进行中',revising:'正在按评价修正',repair:'正在按评价修正',validating:'正在检查课程约束',complete:'计划草案已完成',failed:'本次生成未完成'})[value]||value||'任务已启动'}
function planningFindings(){const trace=planningJob?.review_trace||[];const last=trace.slice().reverse().find(x=>x.stage==='independent_review');const structural=trace.slice().reverse().find(x=>x.stage==='structure');const findings=[...(structural?.issues||[]),...(last?.review?.must_fix||[]),...(last?.review?.issues||[]).map(x=>typeof x==='string'?x:x.message)].filter(Boolean);return findings.length?`<details open><summary>最近一轮仍需解决的问题${last?.review?.score!=null?'（独立评分 '+esc(last.review.score)+'）':''}</summary><ul>${[...new Set(findings)].slice(0,10).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''}
function planningModal(){if(!planningJob)return;const done=planningJob.status==='done',failed=planningJob.status==='failed';showModal(done?'计划草案已准备好':failed?'计划生成未完成':'正在为你制定计划',`<div id="planning-stage" role="status" aria-live="polite"><strong>${esc(planningStage(planningJob.stage))}</strong><p>${esc(planningJob.message||'正在等待后台处理。')}</p>${planningJob.poll_error?`<p class="error">最新查询：${esc(planningJob.poll_error)}</p>`:''}${failed?`<p class="error">${esc(planningJob.error||'生成未能完成，请稍后重试。')}</p>`:''}${planningTime()}</div>${failed?planningFindings():''}<p class="privacy-note">${failed?'已有计划继续保留，可以修改档案后重试。':done?'查看和采用前，已有安排继续保留。':'可以关闭窗口继续使用。任务在后台进行，结果会保留在「计划」页。期间如更新档案或训练记录，需要按新信息重新生成。'}</p><div class="modal-foot"><button class="btn ghost" data-action="close-modal">${failed?'暂时关闭':'稍后查看'}</button>${done?'<button class="btn primary" data-action="planning-result">查看计划草案</button>':failed?'<button class="btn primary" data-action="ai-plan">重新生成</button>':''}</div>`)}
function refreshPlanningBanner(){const banner=$('#planning-banner');if(banner)banner.outerHTML=planningBanner()}
async function pollPlanning(id){if(!planningJob||planningJob.id!==id||planningJob.accountId!==data?.user?.id)return;if(planningPollBusy){clearTimeout(planningPollTimer);planningPollTimer=setTimeout(()=>pollPlanning(id),2500);return}planningPollBusy=true;const accountId=planningJob.accountId;try{const result=await api('/planning/'+encodeURIComponent(id));if(!planningJob||planningJob.id!==id||data?.user?.id!==accountId)return;planningJob={...planningJob,...result,id,accountId,poll_error:null};savePlanning();const visible=modal.open&&!!$('#planning-stage');if(result.status==='done'){planningJob.status='done';proposalId=result.proposal_id||null;savePlanning();refreshPlanningBanner();if(visible&&$('#planning-stage')&&proposalId)await viewProposal(proposalId);else if(visible)planningModal();else toast('新计划草案已准备好，可在「计划」查看。')}else if(result.status==='failed'){refreshPlanningBanner();if(visible)planningModal();else toast('这次生成未完成，原计划已保留。')}else{if(visible){$('#planning-stage').innerHTML=`<strong>${esc(planningStage(result.stage))}</strong><p>${esc(result.message||'任务仍在进行。')}</p>${planningTime()}`}refreshPlanningBanner()}}catch(error){if(planningJob?.id===id&&data?.user?.id===accountId){planningJob.poll_error=error.message;if([401,403,404].includes(error.status)){planningJob.status='failed';planningJob.error=error.message;planningJob.message='无法继续查询这次任务。已有计划继续保留。';refreshPlanningBanner();if(modal.open&&$('#planning-stage'))planningModal()}else{planningJob.message='暂时无法取得最新阶段，正在重试；后台任务不会因关闭窗口而取消。';if(modal.open&&$('#planning-stage'))$('#planning-stage').textContent=planningJob.message+' '+error.message}savePlanning()}}finally{planningPollBusy=false;if(planningJob?.id===id&&planningActive(planningJob)&&planningJob.accountId===data?.user?.id){clearTimeout(planningPollTimer);planningPollTimer=setTimeout(()=>pollPlanning(id),2500)}}}
async function planningRequest(){const estimateOwner=data?.user?.id;if(planningActive(planningJob)){planningModal();return}showModal('这次希望怎样安排？',`<p class="intro">模型会结合完整档案、已有计划和这次要求生成，再独立评审与修正。</p><div class="form-field"><label for="planning-request">具体要求（选填）</label><textarea id="planning-request" maxlength="2000" placeholder="例如：保留上下肢分化；每周两次慢跑；增加拉力训练。请写明真实时长和现有工作重量。"></textarea></div><p id="planning-estimate" class="privacy-note" role="status">正在估算等待时间…</p><p class="privacy-note">先生成草案，采用前不会替换原计划。</p><div class="modal-foot"><button class="btn primary" data-action="ai-plan-submit">开始生成与评审</button></div>`);try{const e=await api('/planning/estimate');if(data?.user?.id!==estimateOwner)return;const label=$('#planning-estimate');if(label)label.textContent=estimateText(e)+'。评审发现问题时可能延长；可关闭窗口稍后查看。'}catch{const label=$('#planning-estimate');if(label)label.textContent='暂时无法取得估时。任务可在后台运行，开始后会显示真实阶段。'}}
async function startPlanning(requestDetail='',sessionId=null,targetProposalId=null){if(!state()?.profile){startOnboard();return}restorePlanning();if(planningActive(planningJob)){planningModal();pollPlanning(planningJob.id);return}showModal('正在提交计划任务',`<p id="planning-submit" role="status">正在保存这次生成请求…</p><p class="privacy-note">新计划会经过生成和评价；查看草案并采用前，已有计划继续保留。</p>`);const accountId=data.user.id;try{const result=await api('/planning','POST',{revision:data.revision,request_detail:requestDetail,...(sessionId?{session_id:sessionId}:{}),...(targetProposalId?{proposal_id:targetProposalId}:{})});if(data?.user?.id!==accountId)return;if(!result.job_id)throw new Error('服务没有返回任务编号，请稍后重试');planningJob={...result,id:result.job_id,accountId,status:result.status||'running',stage:result.stage||'queued',message:result.message||'后台已收到请求，等待生成。'};savePlanning();if(modal.open&&$('#planning-submit'))planningModal();render();pollPlanning(planningJob.id)}catch(error){if(data?.user?.id!==accountId)return;planningJob={accountId,status:'failed',error:error.message,message:'生成请求未完成。已有计划继续保留。'};savePlanning();if(modal.open&&$('#planning-submit'))planningModal();else toast(error.message);render()}}
async function showPlanningResult(){if(!planningJob?.proposal_id)return;await load();await viewProposal(planningJob.proposal_id)}
const planningActive=job=>['queued','running'].includes(job?.status);
async function load(){try{data=await api('/state');restorePlanning();render()}catch(e){if(!data)landing();else toast(e.message)}}
function showModal(title,html){if(timerInterval){clearInterval(timerInterval);timerInterval=null;}modal.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭">${I('close')}</button></div><div class="modal-body">${html}</div>`;if(!modal.open)modal.showModal();modal.scrollTop=0}
function closeModal(){modal.close();if(timerInterval){clearInterval(timerInterval);timerInterval=null;}}
function landing(){if(planningPollTimer)clearTimeout(planningPollTimer);planningJob=null;data=null;app.innerHTML=`<main class="landing"><nav class="landing-nav">${brand()}<button class="btn ghost" data-action="login">登录 / 注册 ${I('arrow')}</button></nav><section class="landing-main"><div><div class="eyebrow">YOUR PACE. YOUR PROGRESS.</div><h1 class="serif">运动有方向，<br>进步有自己的节奏。</h1><p>从你现在的状态出发，一起找到合适的运动安排。<br>生活会变化，计划也可以。每一次小小的坚持，都算数。</p><div class="landing-proof">“今天只有十分钟” → 预览调整 → 采用<br><span>真实反馈留在记录里，下一周接着调整。</span></div><div class="actions"><button class="btn primary" data-action="new-demo">先为我制定计划 ${I('arrow')}</button><button class="btn ghost" data-action="demo">看看示例计划</button></div><p style="font-size:10px;margin-top:22px">不需要手表，也不用先变得自律。就从现在的你开始。</p></div><div class="landing-visual">${art()}<div class="floating-note">今天，做一点适合自己的。<small>认识自己 → 开始行动 → 慢慢进步</small></div></div></section><section class="landing-features"><div>${I('user')}<strong>先了解你，再安排训练</strong><p>目标、时间、兴趣与现状，共同决定你的起点。</p></div><div>${I('calendar')}<strong>安排可以随生活调整</strong><p>忙一点、累一点，或想换一种，都能商量。</p></div><div>${I('growth')}<strong>看到进步，也理解进步</strong><p>用实际反馈调整下一步，逐渐学会怎么练。</p></div></section>${footer()}</main>`}
function footer(){return `<footer class="footer"><span>WAYWISE · 帮助希望提升的人提升　<button class="text-btn" data-action="privacy">数据与隐私</button></span><span>一般运动建议 · 不替代医疗或专项指导　<a href="https://beian.miit.gov.cn/" target="_blank" rel="noopener">沪ICP备2025127932号</a></span></footer>`}
function accountEntry(){return data.user.demo?`<button class="account-entry" data-action="login">${I('user')}<span>登录 / 注册</span></button>`:`<button class="account-entry" data-action="account" aria-label="打开我的账号">${I('user')}<span>我的账号</span></button>`}
function accountCard(){return `<section class="card account-card"><div><h2>${data.user.demo?'登录后保存你的运动旅程':'我的账号'}</h2><p>${data.user.demo?'当前是试用空间；已有账号可直接用邮箱登录。':esc(data.user.email)}</p></div><button class="btn primary" data-action="${data.user.demo?'login':'account'}">${I('user')}${data.user.demo?'登录 / 注册':'管理账号'}</button></section>`}
function accountMenu(){showModal('我的账号',`<p class="intro">${esc(data.user.email)}</p><p class="small-text muted">运动档案、提醒设置和数据管理都在「我的」。</p><div class="stack"><button class="btn primary" data-action="account-settings">${I('user')} 进入个人管理</button><button class="btn ghost" data-action="logout">${I('logout')} 退出登录 / 切换账号</button></div>`)}
function render(){if(!data)return landing();restorePlanning();const p=state().profile;const labels={today:'今天',plan:'计划',growth:'成长',me:'我的'};app.innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="brand-note">找到自己的运动节奏</div><nav class="nav" aria-label="主导航">${Object.entries(labels).map(([id,label])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${I({today:'home',plan:'calendar',growth:'growth',me:'user'}[id])}<span>${label}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-quote">慢慢来，<br>每一步都在靠近。</div><div class="profile-chip"><div class="avatar">${esc((p?.name||'你').slice(0,1))}</div><div><strong>${esc(p?.name||'新的开始')}</strong><small>${data.user.demo?(state().demo_mode==='empty'?'独立试用空间':'独立演示空间'):'我的运动旅程'}</small></div><button class="text-btn" data-action="logout" aria-label="退出" style="margin-left:auto">${I('logout')}</button></div></div></aside><main class="workspace"><header class="topbar"><div class="crumb">我的运动旅程 ${I('chevron')} <span>${labels[page]}</span></div><span class="mobile-brand">${brand()}</span><div class="top-actions"><span class="date-label">${esc(fmt(data.today,{year:'numeric',month:'long',day:'numeric',weekday:'long'}))}</span>${data.user.demo?`<span class="pill demo">${state().demo_mode==='empty'?'从零试用':'示例体验'}</span>`:''}${accountEntry()}<button class="icon-btn" data-action="notices" aria-label="查看提醒">${I('bell')}${data.notices.some(n=>!n.read)?'<span class="dot"></span>':''}</button></div></header><div class="page">${data.user.demo&&state().demo_mode!=='empty'?`<div class="banner demo-banner"><p>你正在查看虚构的示例计划和运动记录。</p><button class="text-btn" data-action="new-demo">从零制定我的计划 ${I('arrow')}</button></div>`:''}${state().risk?.message?`<div class="banner">${I('shield')}<p>${esc(state().risk.message)}</p><button class="text-btn" data-action="onboard">更新身体情况 ${I('arrow')}</button></div>`:''}${({today:todayPage,plan:planPage,growth:growthPage,me:mePage}[page])()}</div>${footer()}</main></div>`;if(!drawer.hidden)renderCoach()}
function heading(en,title,sub,right=''){return `<div class="eyebrow">${en}</div><div class="heading-row"><div><h1 class="serif">${title}</h1><p class="subheading">${sub}</p></div>${right}</div>`}
function noProfile(){return `<div class="card empty"><div class="empty-icon">${I('leaf')}</div><h2 class="serif">从了解现在的你开始</h2><p>告诉我你的运动现状、目标和可用时间。<br>我们一起找到第一周合适的安排。</p><button class="btn primary" data-action="onboard">建立我的运动档案 ${I('arrow')}</button></div>`}
function weekRail(plan){if(!plan)return '';return `<div class="week-rail">${plan.sessions.map(s=>{const d=new Date(s.date+'T12:00:00'),r=recordFor(s);return `<button class="day ${s.date===data.today?'today':''} ${isDone(s)?'done':''} ${selected===s.id?'selected':''}" data-action="select-day" data-id="${s.id}" aria-label="${esc(fmt(s.date))} ${esc(s.title)}"><span class="weekday">${dayNames[(d.getDay()+6)%7]}</span><span class="day-number">${d.getDate()}</span><span class="day-mark">${I(isDone(s)?'check':iconFor(s))}</span><span class="day-type">${r?({completed:'已完成',partial:'部分完成',skipped:'未完成',rest:'已休息'}[r.status]):kindNames[s.kind]}</span></button>`}).join('')}</div>`}
function weekCard(plan,detail=false){return `<section class="card week-card ${detail?'':'section'}"><div class="card-header"><h2>${detail?'一周的安排':'这一周，稳稳向前'}</h2><span class="mini">${fmt(plan.week,{month:'numeric',day:'numeric'})} — ${fmt(dateAdd(plan.week,6),{month:'numeric',day:'numeric'})}</span></div>${weekRail(plan)}${detail?trainingDetail(plan.sessions.find(s=>s.id===selected)||plan.sessions.find(s=>s.date===data.today)||plan.sessions[0]):''}</section>`}
function progressCard(){const s=data.stats,ratio=s.planned?Math.min(1,s.completed/s.planned):0;return `<section class="card"><div class="card-header"><h2>本周的小积累</h2><span class="mini">${s.unknown?'含 '+s.unknown+' 次未知记录':'每一次都算数'}</span></div><div class="week-progress"><div class="ring"><svg viewBox="0 0 110 110"><circle cx="55" cy="55" r="47" fill="none" stroke="#eff2e8" stroke-width="7"/><circle cx="55" cy="55" r="47" fill="none" stroke="#829b5d" stroke-width="7" stroke-linecap="round" stroke-dasharray="${ratio*295.3} 295.3"/></svg><div class="ring-label"><strong>${s.completed}<small> / ${s.planned}</small></strong><span>已记录活动</span></div></div><div class="ring-description"><strong>${s.completed?'给自己一点肯定':'第一步，可以很小'}</strong><p>已经活动了 ${s.minutes} 分钟<br>${s.completed?'继续保持自己的节奏。':'按今天适合你的安排开始。'}</p></div></div><div class="progress-foot"><span>原始 / 当前计划</span><strong>${s.original_minutes} / ${s.planned_minutes} 分钟</strong></div></section>`}
function miniChart(){const points=[];for(let w=3;w>=0;w--){const end=dateAdd(data.today,-7*w+1),start=dateAdd(end,-7);points.push(state().records.filter(r=>r.date>=start&&r.date<end&&['completed','partial'].includes(r.status)).reduce((a,r)=>a+r.minutes,0))}const max=Math.max(...points,30),xs=[10,90,170,250],ys=points.map(v=>90-v/max*65);return `<svg class="mini-chart" viewBox="0 0 260 105" role="img" aria-label="最近四周活动分钟数 ${points.join('、')}"><path d="M10 25H250M10 57H250M10 90H250" stroke="#eff1e9" stroke-dasharray="3 5"/><path d="M${xs.map((x,i)=>x+','+ys[i]).join(' L')} L250,100 L10,100Z" fill="#edf2e1"/><path d="M${xs.map((x,i)=>x+','+ys[i]).join(' L')}" stroke="#829b5d" fill="none" stroke-width="2"/>${points.map((v,i)=>`<circle cx="${xs[i]}" cy="${ys[i]}" r="3" fill="#829b5d"/><text x="${xs[i]}" y="${ys[i]-10}" font-size="9" text-anchor="middle" fill="#8a957c">${v}</text>`).join('')}</svg><div class="chart-labels"><span>四周前起</span><span>最近一周</span></div><div class="legend">实际记录的活动时长 · 分钟</div>`}
function todayPage(){const p=state().profile;if(!p)return heading('A FRESH START','你好，新的开始。','不用一次改变很多，先找到适合自己的第一步。')+noProfile();const s=focusSession(),r=s?recordFor(s):null,done=isDone(s),rest=!s||s.kind==='rest';return `${heading('A LITTLE EVERY DAY',`${esc(p.name)}，今天也向前一点。`,'不着急追赶谁，找到自己的节奏就好。',`<div class="today-tools"><span class="pill">${esc(state().plan?.phase||'认识自己')}</span></div>`)}<div class="grid-main"><div><section class="hero"><div class="hero-text"><div class="hero-kicker">${I(rest?'leaf':'sun')} ${done?'今天的积累已记下':s?.date===data.today?'为今天准备的安排':'留一点空间，给自己'}</div><h2 class="serif">${!s?'今天尚未安排训练。':rest?'今天好好恢复，<br>也是在向前。':done?(r.status==='partial'?'完成一点，<br>也值得记下。':'又一次，<br>为自己做到。'):esc(s.title)}</h2><p>${esc(done?'身体的改变需要时间，今天的行动已经是其中一部分。':s?.purpose||(state().upcoming?'新计划从 '+fmt(state().upcoming.week)+' 开始，可先在「计划」查看。':'可在「计划」生成安排，也可以先记录自主训练。'))}</p>${!rest?`<div class="hero-meta"><span>${I('clock')}${done?(r.minutes===0?'实际不足 1 分钟':'实际 '+r.minutes+' 分钟'):s.minutes+' 分钟计划'}</span><span>${done?'原安排 '+s.minutes+' 分钟':I(iconFor(s))+kindNames[s.kind]}</span>${done?'':`<span>${I('leaf')}${esc(s.intensity||'按体感调整')}</span>`}</div>`:''}</div>${art()}<div class="hero-actions"><button class="btn primary" data-action="${done?'feedback':rest?'free-record':'training'}" ${s&&!rest?`data-id="${s.id}"`:''}>${I(done?'check':rest?'edit':'play')}${done?'查看 / 修改反馈':rest?'记录自主活动':'看看今天怎么练'}</button><button class="text-btn" data-action="coach">${rest?'和教练聊聊':'今天想调整一下'} ${I('arrow')}</button></div></section>${state().plan?weekCard(state().plan):''}<div class="two-cards section"><section class="card insight"><div class="insight-label">${I('book')} 今天，懂一点运动</div><blockquote class="serif">“适合自己的安排，<br>才有机会变成习惯。”</blockquote><p>忙碌时缩短一点，疲惫时缓一缓。<br>调整是为了继续，记录帮你认识自己。</p><button class="text-btn" data-action="learn" style="margin-top:17px">为什么不需要补欠课 ${I('arrow')}</button></section><section class="card"><div class="card-header"><h2>进步，有自己的路线</h2>${I('growth')}</div><div class="route-mini"><div class="route-dot">01</div><div><strong>认识现在的自己</strong><small>找到起点和生活中的空间</small></div><span class="status-tag">已开始</span></div><div class="route-mini"><div class="route-dot">02</div><div><strong>练出可以持续的节奏</strong><small>用每次反馈调整下一步</small></div><span class="status-tag">进行中</span></div><div class="route-mini"><div class="route-dot">03</div><div><strong>准备好了，再向前一点</strong><small>根据实际表现与恢复决定</small></div></div></section></div></div><div class="right-column">${progressCard()}<section class="card coach-card section"><div class="card-header"><h2>你的运动教练</h2><div class="coach-spark">${I('spark')}</div></div><p>${esc(data.direction[1])}</p><button class="btn lime" data-action="coach">聊聊我的安排 ${I('arrow')}</button><div class="coach-suggestions"><button data-action="quick-coach" data-text="今天只有十分钟">今天时间有点紧</button><button data-action="quick-coach" data-text="今天想换成室内活动">想换一种练法</button></div></section><section class="card trend-card section"><div class="card-header"><h2>慢慢积累的变化</h2><button class="text-btn" data-page="growth">查看 ${I('arrow')}</button></div>${miniChart()}</section></div></div>`}
function workoutStep(s,x,i,swap=false){const opt=x.alternatives?.[0];const dose=x.sets?`${x.sets} 组 × ${x.work_seconds!=null?x.work_seconds+' 秒':(x.rep_max?x.reps+'–'+x.rep_max:x.reps)+' 次'}${x.each_side?' / 每侧':''}${x.sets>1?' · 组间休息 '+x.rest_seconds+' 秒':''}${x.rest_after_last?' · 末组后休息 '+x.rest_seconds+' 秒':''}`:x.rounds?`${x.rounds===1?'1 个计时块':x.rounds+' 轮'} · 工作 ${x.work_seconds??'按说明'} 秒${x.each_side?' / 每侧':''} · 恢复 ${x.rest_seconds??0} 秒${x.rest_after_last?'（含末轮后）':''}`:x.dose||'按动作要领进行';return `<div class="step step-compact"><div class="step-index">${String(i+1).padStart(2,'0')}</div><div class="step-content"><strong>${esc(x.title)}</strong><p class="dose">${esc(dose)}</p>${x.intensity?`<p class="step-intensity">${esc(x.intensity)}</p>`:''}<div class="step-links"><button class="text-btn small-text" data-action="movement-guide" data-id="${esc(s.id)}" data-step="${i}">动作图解</button><details class="step-explanation"><summary>为什么这样练</summary><div><p>${esc(x.benefit||'这一步服务于本次课程的训练重点，可以继续向教练确认具体取舍。')}</p>${x.rationale?`<p>${esc(x.rationale)}</p>`:''}<p><b>动作要领：</b>${esc(x.detail)}</p>${x.tempo?`<p><b>动作节奏：</b>${esc(x.tempo)}</p>`:''}${x.caution?`<p><b>注意：</b>${esc(x.caution)}</p>`:''}${x.stop_rule?`<p><b>停止条件：</b>${esc(x.stop_rule)}</p>`:''}${x.suggested_alternatives?.length?`<p><b>可讨论的替代：</b>${x.suggested_alternatives.map(esc).join('、')}</p>`:''}${swap&&opt&&typeof opt==='object'?`<button class="text-btn small-text" data-action="swap-step" data-id="${esc(s.id)}" data-step="${i}">预览替代：${esc(opt.title)}</button>`:''}<button class="text-btn small-text" data-action="ask-step-why" data-id="${esc(s.id)}" data-step="${i}">问教练这个动作</button></div></details></div></div><span class="step-time">${x.minutes} 分钟</span></div>`}
function showMovementGuide(id,index){const session=sessionBy(id),step=session?.steps?.[index];if(!step)return;guideReturnSession=id;guideReturnTraining=modal.open&&!!$('#timer-value');guideReturnProposal=modal.open&&modal.querySelector('[data-action="apply-proposal"]')?previewProposalId:null;const guide=globalThis.SportsWiseMovementGuides;showModal(step.title+' · 动作图解',`${guide?guide.render(step.title,step.movement_pattern||''):'<p class="guide-disclaimer">动作示意暂未加载。请先核对本动作文字说明，不以相似动作图代替。</p>'}<section class="movement-instructions"><h3>这次动作怎么做</h3><p>${esc(step.detail)}</p>${step.tempo?`<p><b>节奏：</b>${esc(step.tempo)}</p>`:''}${step.caution?`<p><b>注意：</b>${esc(step.caution)}</p>`:''}${step.stop_rule?`<p><b>停止条件：</b>${esc(step.stop_rule)}</p>`:''}${!step.caution&&!step.stop_rule?'<p class="small-text muted">异常不适时先停止，不为完成次数继续。</p>':''}</section><details class="sources"><summary>参考资料</summary><p><a href="https://www.nhs.uk/live-well/exercise/strength-exercises/" target="_blank" rel="noopener">NHS 基础力量动作说明</a>。复杂技能请向合格教练核对。</p></details><div class="modal-foot"><button class="btn ghost" data-action="ask-step-why" data-id="${esc(id)}" data-step="${index}">和教练讨论</button><button class="btn primary" data-action="guide-back">${guideReturnTraining?'返回训练计时':'返回课程'}</button></div>`)}
function sessionReason(s){return `<details class="session-reason"><summary>为什么安排这堂课</summary><p>${esc(s.rationale||s.purpose)}</p>${s.progression_rule?`<p><b>何时调整：</b>${esc(s.progression_rule)}</p>`:''}<button class="text-btn" data-action="ask-session-why" data-id="${esc(s.id)}">和教练讨论这堂课</button></details>`}
function planLearning(plan){const focus=plan.learning_focus;const items=Array.isArray(plan.decisions)?plan.decisions:[];return `<details class="plan-reason plan-learning"><summary>了解这周的安排与取舍</summary>${focus?`<p>${esc(Array.isArray(focus)?focus.join('；'):focus)}</p>`:''}<p>${esc(plan.rationale||plan.reason)}</p>${items.map(d=>`<article><strong>${esc(d.topic||d.reason||d.title||'安排依据')}</strong>${d.topic&&d.reason?`<p>${esc(d.reason)}</p>`:''}${d.evidence?`<p>依据：${esc(d.evidence)}</p>`:''}${d.tradeoff?`<p>取舍：${esc(d.tradeoff)}</p>`:''}${d.change_signal?`<p>调整信号：${esc(d.change_signal)}</p>`:''}</article>`).join('')}<button class="text-btn" data-action="quick-coach" data-text="请结合我的档案解释这周安排的原因、主要取舍和需要调整的信号，先讨论，不修改计划。">和教练聊聊安排原因</button></details>`}
const muscleName=k=>({quadriceps:'大腿前侧',quads:'大腿前侧',hamstrings:'大腿后侧',glutes:'臀部',back:'背部',chest:'胸部',shoulders:'肩部',biceps:'肱二头肌',triceps:'肱三头肌',core:'躯干',calves:'小腿',forearms:'前臂',hip_abductors:'髋外展肌',hip_adductors:'髋内收肌'}[k]||k);
function muscleDose(x){return x.strength_sets!=null||x.power_sets!=null?`${x.strength_sets||0} 力量组 / ${x.power_sets||0} 爆发组`:`${x.sets} 工作组`}
function trainingMix(plan){if(!plan)return '';const aerobic=['walk','indoor','run','bike','badminton','dance'];const tracks=[['有氧代谢',s=>aerobic.includes(s.kind),'用可恢复的有氧积累心肺与线粒体适应所需的训练刺激。'],['肌力与肌肉',s=>s.kind==='strength','观察能完成的组数、动作控制和余力，再决定是否进阶。'],['骨骼负荷',s=>['strength','walk','run','badminton','dance'].includes(s.kind),'标记抗阻或负重活动。课表不能测量骨密度。']];return `<section class="card"><div class="card-header"><h2>这周为什么这样练</h2></div><details class="weekly-detail"><summary>查看训练方向、周剂量与进阶</summary><div class="mix-grid">${tracks.map(([label,include,why])=>{const ss=plan.sessions.filter(include);return `<div><strong>${label}</strong><span>${ss.length} 节 · ${ss.reduce((a,s)=>a+s.minutes,0)} 分钟</span><p>${why}</p></div>`}).join('')}</div>${plan.programming?`<div class="programming-note"><h3>剂量与下一步</h3>${plan.programming.direct_sets.length?`<p>${plan.programming.direct_sets.map(x=>esc(muscleName(x.muscle))+' '+esc(muscleDose(x))).join(' · ')}</p>`:''}<p class="small-text muted">${esc(plan.programming.scope)}</p>${plan.programming.missing.length?`<p class="privacy-note">仍需校准：${plan.programming.missing.map(esc).join('；')}。可在「我的」补充训练基线。</p>`:''}<p>${esc(plan.programming.progression)}</p><p class="small-text muted">${esc(plan.programming.deload)}</p><p class="small-text muted">${esc(plan.programming.review)}</p></div>`:''}<p class="small-text muted">同一课程可能支持多个方向；以上是安排量，不是身体指标。</p>${planSources(plan)}</details></section>`}
function loadPanel(){const flags=data.load_flags||[];if(!flags.length)return '';return `<section class="card load-panel"><div class="card-header"><h2>哪些项目练得比计划多</h2>${I('growth')}</div>${flags.map(f=>`<div class="load-item"><strong>${esc(f.label)}</strong><p>${f.windows.map(w=>`${fmt(w.start)}–${fmt(w.end)}：实际 ${w.actual} 分钟 / 计划 ${w.planned} 分钟`).join('<br>')}</p><p><b>下一步：</b>${esc(f.advice)}</p></div>`).join('')}<p class="small-text muted">按你记录的活动和个人课表比较。连续超量提示适当恢复，不代表已经受伤。</p><button class="btn ghost small" data-action="next-draft">预览下周负荷调整 ${I('arrow')}</button></section>`}
function trainingDetail(s){if(!s)return '';const record=recordFor(s),futureQueued=!!state().upcoming?.sessions.some(x=>x.id===s.id);return `<div class="training-detail"><div class="training-title"><div><h3>${esc(s.title)}</h3><span class="muted small-text">${fmt(s.date,{month:'long',day:'numeric',weekday:'long'})}${s.period_adjusted?' · 已按经期感受调整':''}</span></div>${s.kind!=='rest'?`<span class="pill">${s.minutes} 分钟</span>`:''}</div>${s.kind!=='rest'?`<p class="session-intensity">${esc(s.intensity||'按体感调整')}</p>`:''}${sessionReason(s)}${s.steps.map((x,i)=>workoutStep(s,x,i,!!data.session_options?.[s.id]?.length)).join('')}${s.kind==='rest'?'<p class="small-text muted">不需要补课，按自己的感受恢复。</p>':''}${record?`<p class="privacy-note">已记录：${{completed:'完整完成',partial:'部分完成',skipped:'未完成',rest:'休息'}[record.status]} · ${record.minutes} 分钟 · ${{easy:'轻松',okay:'合适',hard:'吃力'}[record.effort]}${record.note?' · '+esc(record.note):''}</p>`:''}<div class="actions">${s.kind!=='rest'&&s.date===data.today&&!record?`<button class="btn primary" data-action="training" data-id="${s.id}">${I('play')} 开始这次训练</button>`:''}${s.date<=data.today&&s.kind!=='rest'?`<button class="btn ${record?'ghost':'primary'}" data-action="feedback" data-id="${s.id}">${I('edit')}${record?'修改反馈':'记录完成情况'}</button>`:''}${s.kind!=='rest'&&s.date>=data.today&&!record&&(!futureQueued||data.session_options?.[s.id]?.length)?`<button class="btn ghost" data-action="adjust" data-id="${s.id}">调整这次安排</button>`:''}${s.kind==='rest'&&s.date<=data.today?'<button class="btn ghost" data-action="free-record">记录自主活动</button>':''}</div><div class="sources">动作时间包含休息，不要求持续重复。有异常不适时先停止。<br>参考：<a href="https://www.nhs.uk/live-well/exercise/strength-exercises/" target="_blank" rel="noopener">NHS 基础力量动作</a> · <a href="https://www.niddk.nih.gov/health-information/weight-management/tips-get-active/tips-starting-physical-activity" target="_blank" rel="noopener">从少量活动开始</a></div></div>`}
function planPage(){const p=state().plan;if(!p)return heading('MAKE ROOM FOR MOVEMENT','给运动，留一点位置。','计划从你的生活出发，也可以随着生活调整。')+planningBanner()+(state().profile?'<section class="card"><p>档案已保存，可以生成一份计划草案，核对后再采用。</p><button class="btn primary" data-action="ai-plan">生成 AI 训练计划</button><button class="btn ghost" data-action="onboard">修改档案</button></section>':noProfile());return `${heading('YOUR WEEK, YOUR WAY','安排有方向，也有余地。','计划不是一张不能改的课表，是我们一起商量的下一步。',`<div class="actions"><button class="btn primary small" data-action="ai-plan">${I('spark')} 重新生成 AI 计划</button><button class="btn ghost small" data-action="onboard">${I('edit')} 修改偏好</button></div>`)}${planningBanner()}<div class="grid-main"><div class="stack">${planLearning(p)}${weekCard(p,true)}${trainingMix(p)}${loadPanel()}${state().upcoming?`<div class="card"><div class="card-header"><h2>下一周也有了方向</h2><span class="badge">${fmt(state().upcoming.week)}</span></div><p class="small-text muted">${esc(state().upcoming.reason)}</p>${weekRail(state().upcoming)}${selected&&state().upcoming.sessions.some(s=>s.id===selected)?trainingDetail(state().upcoming.sessions.find(s=>s.id===selected)):''}<p class="small-text muted">到新一周时自动接上。今天仍按本周安排进行。如需改变长期偏好，可修改运动档案后重新安排。</p></div>`:''}<section class="card"><div class="card-header"><h2>计划改变的轨迹</h2>${state().history.some(x=>x.week===p.week&&x.policy===p.policy)?'<button class="text-btn" data-action="undo">撤回上次调整 '+I('history')+'</button>':''}</div><div class="version-list"><strong>当前 · 第 ${p.version} 版</strong><p>${esc(p.reason)}</p></div>${state().history.filter(x=>x.week===p.week).slice(-3).reverse().map(x=>`<div class="version-list"><strong>第 ${x.version} 版</strong><p>${esc(x.reason)}</p></div>`).join('')}</section></div><div class="stack"><section class="card insight"><div class="card-header"><h2>这一阶段：${esc(p.phase)}</h2>${I('leaf')}</div><div class="timeline"><div class="timeline-item current"><h3>找到合适的起点</h3><p>先熟悉安排，留意活动后和第二天的感受。</p></div><div class="timeline-item"><h3>把反馈带进下一周</h3><p>时间不合适就调整，觉得吃力就缓一缓。</p></div><div class="timeline-item"><h3>准备好了，再进阶</h3><p>需要真实训练和恢复反馈，不按日期自动加量。</p></div></div></section><section class="card"><div class="card-header"><h2>下一周，怎么安排？</h2>${I('calendar')}</div><p class="small-text muted">${esc(data.direction[1])}</p>${state().upcoming?'<span class="pill">下一周已经安排好</span>':`<button class="btn primary" data-action="next-week">预览下一周安排 ${I('arrow')}</button>`}</section><section class="card coach-card"><div class="card-header"><h2>生活变了，计划也能变</h2>${I('spark')}</div><p>加班、出差，或者只想轻松一点。告诉我，我们一起调整。</p><button class="btn lime" data-action="coach">和教练商量 ${I('arrow')}</button></section></div></div>`}
function growthGarden(){const garden=data.growth?.garden;if(!garden)return '';const selected=garden.plots.find(x=>x.kind===gardenPlot)||garden.plots.find(x=>x.count)||garden.plots[0];return `<section class="card growth-garden"><div class="card-header"><div><div class="eyebrow">记录一次，点亮一处</div><h2>我的运动花园</h2></div><span class="pill">${esc(garden.stage)}</span></div><p class="garden-intro">${garden.total} 次运动留下了足迹，已点亮 ${garden.variety} / ${garden.plots.length} 种景物。</p><div class="garden-grid" role="group" aria-label="花园景物">${garden.plots.map(plot=>`<button class="garden-tile ${plot.count?'unlocked':''}" data-action="garden-plot" data-kind="${plot.kind}" aria-pressed="${plot.kind===selected.kind}" aria-label="${esc(plot.name)}，${plot.count?plot.count+' 次':'待点亮'}"><span class="garden-icon" aria-hidden="true">${plot.icon}</span><strong>${esc(plot.name)}</strong><small>${plot.count?'× '+plot.count:'待点亮'}</small></button>`).join('')}</div><p class="garden-caption" aria-live="polite"><strong>${esc(selected.activity)} → ${esc(selected.name)}</strong> · ${selected.count?'已有 '+selected.count+' 次记录':'记一次这种活动就能点亮'}</p><p class="small-text muted">做完或只做了一部分，每条都给花园留一份足迹。时间更长、心率更高也不会额外加分。</p></section>`}
function growthReport(){const report=data.growth?.[growthCadence],a=report?.analysis,prev=a?.comparison;const archives=state().reviews.filter(r=>r.cadence===growthCadence&&r.id!==report?.id).sort((a,b)=>b.start.localeCompare(a.start)).slice(0,3);const to=growthCadence==='week'?'本周':'本月';return `<section class="card growth-report"><div class="card-header"><h2>运动回顾</h2><div class="growth-toggle" role="group" aria-label="选择回顾周期"><button data-action="growth-period" data-cadence="week" aria-pressed="${growthCadence==='week'}">本周</button><button data-action="growth-period" data-cadence="month" aria-pressed="${growthCadence==='month'}">本月</button></div></div>${report&&a?`<p class="mini">${fmt(report.start)} – ${fmt(data.today)} · 截至今天 · 随记录更新</p><h3 class="serif">${esc(report.headline)}</h3><p>${esc(report.summary)}</p>${report.praise.length?`<div class="growth-praise"><strong>${I('spark')} 这些事做得好</strong><ul>${report.praise.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}${a.sessions?`<h4>${to}运动量</h4><ul class="growth-mix">${a.breakdown.map(x=>`<li><strong>${esc(x.label)}</strong><span>${x.sessions} 次 · ${x.minutes} 分钟</span></li>`).join('')}</ul><p class="small-text muted">体感：轻松 ${a.easy} 次 · 合适 ${a.okay} 次 · 吃力 ${a.hard} 次${a.heart_rate_count?'。平均心率已记录 '+a.heart_rate_count+' 次':''}。</p>`:''}${prev?`<p class="growth-compare">和${esc(prev.scope)}前 ${prev.days} 天相比：实际活动 <strong>${prev.actual_minutes} / ${prev.previous_minutes} 分钟</strong>，活动日 <strong>${prev.active_days} / ${prev.previous_active_days} 天</strong>。</p>`:''}<div class="growth-next"><strong>下一步可以这样做</strong><p>${esc(report.next)}</p></div>${state().profile?`<div class="actions"><button class="btn ghost small" data-action="next-week">看看下一周怎么安排 ${I('arrow')}</button></div>`:''}`:'<p>记一次运动后，这里会分析你的运动情况。</p>'}${archives.length?`<details class="growth-archive"><summary>查看过往回顾</summary>${archives.map(r=>`<article><strong>${fmt(r.start)} – ${fmt(dateAdd(r.end,-1))}</strong><p>${esc(r.summary)}</p>${r.praise?.length?`<p>${r.praise.map(esc).join(' ')}</p>`:''}<p><b>下一步：</b>${esc(r.next)}</p></article>`).join('')}</details>`:''}</section>`}
function growthPage(){return `${heading('MOVE, RECORD, GROW','我的运动成长','运动完就记一笔，看看你做到的事和下一步怎么练。')}<section class="growth-record-hero"><div><strong>今天动了什么？</strong><p>散步、力量、打球……计划外的运动也算。</p></div><button class="btn primary" data-action="free-record">${I('edit')} 记录一次运动</button></section><div class="grid-main growth-layout"><div class="stack">${growthReport()}${loadPanel()}<section class="card"><div class="card-header"><h2>最近四周的活动</h2><span class="mini">实际分钟数</span></div>${miniChart()}</section></div><div class="stack">${growthGarden()}<section class="card"><div class="card-header"><h2>最近的运动记录</h2><span class="mini">${state().records.length} 条</span></div>${state().records.length?state().records.slice(-8).reverse().map(r=>`<div class="record-row"><div class="record-icon">${I(r.status==='rest'?'leaf':r.status==='skipped'?'history':'check')}</div><div><p>${esc(r.activity||sessionBy(r.session_id)?.title||'训练记录')}</p><small>${fmt(r.date,{month:'numeric',day:'numeric'})} · ${{completed:'完成',partial:'部分完成',skipped:'未完成',rest:'休息'}[r.status]} · ${r.minutes} 分钟${r.avg_heart_rate!=null?' · 平均心率 '+r.avg_heart_rate+' 次/分':''}</small></div>${r.source!=='demo'?`<button class="text-btn growth-edit" data-action="edit-growth-record" data-id="${esc(r.id)}" aria-label="编辑${esc(r.activity||'这次运动')}">${I('edit')} 编辑</button>`:''}</div>`).join(''):'<p class="small-text muted">这里会留下你的实际活动记录。</p>'}</section></div></div>`}
function mePage(){const p=state().profile,s=state().settings;return `${heading('GET TO KNOW YOURSELF','了解自己，才好向前。','你的目标、现实生活和身体感受，都值得被认真对待。')}${accountCard()}<div class="settings-grid"><div class="stack"><section class="card"><div class="card-header"><h2>我的运动档案</h2><button class="text-btn" data-action="onboard">${I('edit')} ${p?'修改':'建立'}</button></div>${p?`<p class="profile-brief">${esc(goalNames[p.goal]||p.goal)} · 每次最多 ${p.minutes} 分钟</p><details class="profile-fold"><summary>查看完整运动档案</summary><dl class="profile-summary"><div><dt>我的称呼</dt><dd>${esc(p.name)}</dd></div><div><dt>当前目标</dt><dd>${goalNames[p.goal]}</dd></div><div><dt>具体目标</dt><dd>${esc(p.goal_detail)||'暂未补充'}</dd></div><div><dt>制定方式</dt><dd>${esc(({fresh_start:'制定完整新方案',preserve_structure:'保留训练结构，细化与优化',adaptive:'结合基础一起调整'})[p.planning_style]||'结合基础一起调整')}</dd></div><div><dt>保留的周结构</dt><dd>${esc(p.training_structure)||'暂未指定'}</dd></div><div><dt>训练背景</dt><dd>${esc(p.training_background)||'暂未补充'}</dd></div><div><dt>训练基线</dt><dd>${p.training_months!=null?p.training_months+' 个月规律抗阻训练<br>':''}${esc(p.routine_detail)||'暂未补充动作与负荷'}</dd></div><div><dt>为什么运动</dt><dd>${esc(p.motivation)||'暂未填写'}</dd></div><div><dt>当前状态</dt><dd>${esc(p.current)||({beginner:'刚开始运动',returning:'重新开始',regular:'规律运动，想维持或提升',advanced:'进阶训练',competitive:'竞技 / 高水平训练'}[p.level])}</dd></div><div><dt>可用时间</dt><dd>${p.days.map(i=>dayNames[i]).join('、')}<br>每次最多 ${p.minutes} 分钟</dd></div><div><dt>喜欢的方式</dt><dd>${p.likes.map(x=>activityNames[x]).join('、')}</dd></div><div><dt>运动偏好补充</dt><dd>${esc(p.activity_detail)||'暂无'}</dd></div><div><dt>常用场地</dt><dd>${esc(({gym:'健身房',mixed:'多个场地',home:'在家',outdoor:'户外'})[p.place]||p.place)}</dd></div><div><dt>可用器械</dt><dd>${(p.equipment||[]).map(k=>esc(({bodyweight:'自重',dumbbell:'哑铃',band:'弹力带',treadmill:'跑步机',stationary_bike:'健身车',barbell:'杠铃',rack:'深蹲架',bench:'训练凳',cable:'绳索器械',machine:'固定器械',pullup:'单杠',kettlebell:'壶铃',rower:'划船机',ski_erg:'滑雪机',sled:'雪橇',medicine_ball:'药球',box:'跳箱',suspension:'悬吊训练带',other:'其他'})[k]||k)).join('、')}<br>${esc(p.equipment_detail)}</dd></div><div><dt>身体限制</dt><dd>${esc(p.limitations)||'未报告特殊限制'}<small class="muted">（你的自述）</small></dd></div></dl></details>`:'<p class="small-text muted">先建立一份档案，让安排从你现在的状态出发。</p><button class="btn primary" data-action="onboard">开始建立</button>'}</section>${p?.sex==='female'&&!state().blocked?`<section class="card body-feedback"><details><summary>身体反馈与临时调整</summary><p class="small-text muted">按当前感受选择临时调整，之后接回原安排。</p>${periodButton()}</details></section>`:''}<section class="card"><div class="card-header"><h2>数据由你掌握</h2>${I('shield')}</div><p class="small-text muted">必要训练记录和反馈保存在服务端，用于跨次调整和定期复盘。个人计划默认私密。使用 AI 教练时，会发送必要档案、近期记录和对话作为上下文。</p><div class="privacy-note">${data.user.demo?(state().demo_mode==='empty'?'这是从零开始的独立试用空间。首次注册时可选择保存这次资料；试用期间不会发送邮件。':'你正在独立示例空间中。历史记录是虚构的；修改档案会保留示例历史，也可以从零试用。'):'当前账号：'+esc(data.user.email)}<br>${data.capabilities.ai?'AI 计划会结合档案生成，并经过评价与约束检查；采用前可以预览。':'当前为基础教练模式：规则制定安排，支持有限的中文调整指令。'}<br>${data.capabilities.mail?'邮件通道已配置。':'邮件尚未配置，当前可使用站内提醒。'}</div><div class="actions"><a class="btn ghost" href="/api/export">${I('download')} 导出我的数据</a><button class="btn ghost" data-action="${data.user.demo?'login':'logout'}">${I(data.user.demo?'user':'logout')}${data.user.demo?'登录正式账号':'退出登录'}</button></div><button class="text-btn" data-action="delete" style="color:#a58c78;margin-top:20px">${data.user.demo?'删除演示空间':'删除账号和训练数据'}</button></section></div><section class="card"><div class="card-header"><h2>按你的节奏提醒</h2>${I('bell')}</div><form id="settings-form">${[['daily','训练日前提醒','休息日保持安静'],['weekly','每周复盘','周一回看上周，商量下一步'],['monthly','每月回顾','月初回看上个月的积累'],['followup','未记录时跟进一次','提醒后仍未记录，再轻轻问一下'],['email','同时发送邮件',data.capabilities.mail&&!data.user.demo?'邮件默认不包含身体和健康细节':'当前不可用，站内提醒仍可使用']].map(([name,label,sub])=>`<label class="toggle-row"><span>${label}<small>${sub}</small></span><input type="checkbox" class="switch" name="${name}" ${s[name]?'checked':''} ${name==='email'&&(!data.capabilities.mail||data.user.demo)?'disabled':''} aria-label="${label}"></label>`).join('')}<div class="form-grid" style="margin-top:23px"><div class="form-field"><label for="remind-time">提醒时间</label><input id="remind-time" type="time" name="time" value="${esc(s.time)}" required></div><div class="form-field"><label for="tone">跟进方式</label><select id="tone" name="tone"><option value="gentle" ${s.tone==='gentle'?'selected':''}>轻提醒</option><option value="standard" ${s.tone==='standard'?'selected':''}>标准跟进</option><option value="firm" ${s.tone==='firm'?'selected':''}>更主动地督促</option></select></div><div class="form-field"><label for="quiet-start">安静时段开始</label><input id="quiet-start" type="time" name="quiet_start" value="${esc(s.quiet_start)}" required></div><div class="form-field"><label for="quiet-end">安静时段结束</label><input id="quiet-end" type="time" name="quiet_end" value="${esc(s.quiet_end)}" required></div></div><div class="form-field"><label for="zone">我的时区</label><select id="zone" name="timezone">${['Asia/Shanghai','Asia/Hong_Kong','Asia/Tokyo','Europe/London','America/New_York','America/Los_Angeles','Australia/Sydney'].map(z=>`<option ${s.timezone===z?'selected':''}>${z}</option>`).join('')}</select></div><div class="form-field"><label for="paused">暂停提醒至</label><input id="paused" type="date" name="paused_until" value="${esc(s.paused_until)}"><small>留空表示正常提醒；连续两周没有访问时，主动跟进也会暂停。</small></div><button class="btn primary" type="submit">保存提醒偏好 ${I('check')}</button><p id="settings-error" class="error" role="alert"></p></form></section></div>`}
function login(){showModal('欢迎，开始你的运动旅程',`<p class="intro">用邮箱验证码登录。第一次登录会建立新账号。<br>你的个人训练记录默认私密。</p><form id="login-form"><div class="form-field"><label for="email">邮箱</label><input id="email" name="email" type="email" placeholder="you@example.com" required autocomplete="email"></div><div class="form-field"><label for="invite">邀请码（如需）</label><input id="invite" name="invite" placeholder="内测邀请码" autocomplete="off"></div><div class="flex"><input name="code" inputmode="numeric" maxlength="6" pattern="[0-9]{6}" placeholder="6 位验证码" aria-label="验证码"><button class="btn ghost" type="button" data-action="send-code" style="flex-shrink:0">获取验证码</button></div><div id="login-info" class="small-text muted" style="margin-top:12px"></div>${data?.user.demo&&state()?.demo_mode==='empty'&&state()?.profile?'<label class="check-row"><input type="checkbox" name="import_trial" checked>首次注册时，将这次从零试用的档案和运动记录保存到正式账号</label><small class="muted">已有账号会保留原资料，不用试用数据覆盖。</small>':''}<p class="error" id="login-error" role="alert"></p><div class="modal-foot"><button class="btn primary" type="submit">登录并继续 ${I('arrow')}</button></div></form>`)}
function choice(name,val,label,checked,type='checkbox'){return `<label class="choice"><input type="${type}" name="${name}" value="${esc(val)}" ${checked?'checked':''}><span>${esc(label)}</span></label>`}
function showPeriod(){const period=state().period,left=period?Math.round((Date.parse(period.end)-Date.parse(data.today))/86400000)+1:1;showModal('经期运动调整',`<p class="intro">${period?'当前：'+periodNames[period.mode]+'，持续至 '+fmt(period.end,{month:'long',day:'numeric'})+'（含当天）。':'从今天起，按身体感受临时调整待练课程。'}</p><form id="period-form"><fieldset class="period-choices"><legend>现在感觉怎么样？</legend>${[['normal','状态如常','按原计划训练。'],['ease','有些不适或疲劳','缩短课程，改为轻松有氧或关节活动。'],['rest','明显不适，想休息','训练日改为休息，结束后不补课。']].map(([v,n,desc])=>`<label class="period-choice"><input type="radio" name="mode" value="${v}" ${(period?.mode||'normal')===v?'checked':''}><span><strong>${n}</strong><small>${desc}</small></span></label>`).join('')}</fieldset><div class="form-field"><label for="period-days">从今天起持续几天（含今天）</label><input id="period-days" type="number" name="days" min="1" max="10" value="${left}" required><small>到期后自动恢复原安排，也可以随时提前结束。</small></div><p class="privacy-note">只保存本次调整，不预测周期。经期状态不会发送给 AI 或写入邮件。若疼痛严重、出血异常或感到晕厥，请停止训练并及时就医。</p><p class="error" id="period-error" role="alert"></p><div class="modal-foot">${period?'<button class="btn ghost" type="button" data-action="period-end">结束调整</button>':''}<button class="btn primary" type="submit">保存并更新计划 ${I('check')}</button></div></form>`)}
function startOnboard(){profileDraft=structuredClone(state().profile||{name:'',goal:'habit',motivation:'',current:'',level:'beginner',days:[0,2,5],minutes:20,equipment:['bodyweight'],place:'mixed',likes:['walking','strength'],limitations:'',adult:false,consent:false});onboardStep=0;onboard()}
function onboard(){const p=profileDraft;let body='';if(onboardStep===0)body=`<div class="form-field"><label for="intake-text">先用自己的话，讲讲现状和目标</label><textarea id="intake-text" placeholder="比如：半年没运动，想改善体力。周一周三周日晚上能练，每次20分钟，在家或散步都行。" maxlength="1500"></textarea><small>${data.capabilities.ai?'点击整理时，这段话会发给 AI 提取档案；你可以核对修改。':'当前使用基础规则整理，后面的信息仍可以逐项填写。'}</small><button class="btn ghost" type="button" data-action="intake">${I('spark')} 从这段话整理档案</button><span id="intake-info" class="small-text muted"></span></div><p class="intro">先聊聊你。比起一个漂亮的数字，我们更关心你想让生活发生什么改变。</p><div class="form-field"><label for="name">怎么称呼你</label><input id="name" name="name" value="${esc(p.name)}" maxlength="30" placeholder="你的昵称" required></div><div class="form-field"><label>现在最想实现什么</label><div class="chips">${Object.entries(goalNames).map(([id,n])=>choice('goal',id,n,p.goal===id,'radio')).join('')}</div></div><div class="form-field"><label for="goal-detail">把目标说具体一些（选填）</label><textarea id="goal-detail" name="goal_detail" maxlength="1500" placeholder="例如：背部和肩部增肌；三个月后参加十公里比赛；提高羽毛球移动耐力。">${esc(p.goal_detail||'')}</textarea></div><div class="form-field"><label for="planning-style">希望怎样帮你制定计划</label><select id="planning-style" name="planning_style"><option value="fresh_start" ${p.planning_style==='fresh_start'?'selected':''}>为我制定完整的新方案</option><option value="preserve_structure" ${p.planning_style==='preserve_structure'?'selected':''}>保留我的训练结构，细化与优化</option><option value="adaptive" ${!p.planning_style||p.planning_style==='adaptive'?'selected':''}>结合基础，与我一起调整</option></select></div><div class="form-field"><label for="training-structure">已有或希望保留的周结构</label><textarea id="training-structure" name="training_structure" maxlength="2000" placeholder="例如：2次二区有氧、1次上肢表现、1次下肢表现、2次综合体能；不想大改框架。">${esc(p.training_structure||'')}</textarea></div><div class="form-field"><label for="motivation">用自己的话说说，为什么想运动</label><textarea id="motivation" name="motivation" maxlength="1000" placeholder="比如：下班后有精神一点，周末能陪家人走得更远。">${esc(p.motivation)}</textarea></div>`;else if(onboardStep===1)body=`<p class="intro">不需要先证明自己。告诉我真实的现状，计划会从这里开始。</p><div class="form-field"><label for="current">最近几周，你一般怎么运动</label><textarea id="current" name="current" maxlength="1000" placeholder="比如：偶尔散步，已经半年没规律运动了。">${esc(p.current)}</textarea></div><div class="form-field"><label>哪个更接近你</label><div class="chips">${[['beginner','刚开始运动'],['returning','想重新开始'],['regular','规律运动'],['advanced','进阶训练'],['competitive','竞技 / 高水平训练']].map(([id,n])=>choice('level',id,n,p.level===id,'radio')).join('')}</div></div><div class="form-field"><label for="training-background">训练背景（选填）</label><textarea id="training-background" name="training_background" maxlength="1500" placeholder="运动项目、训练经历、近期周运动量、比赛成绩，或想维持的能力。">${esc(p.training_background||'')}</textarea></div><div class="form-grid"><div class="form-field"><label for="training-months">规律抗阻训练月数（选填）</label><input id="training-months" name="training_months" type="number" min="0" max="720" value="${p.training_months??''}" placeholder="例如 24"></div></div><div class="form-field"><label for="routine-detail">已有训练基线（选填）</label><textarea id="routine-detail" name="routine_detail" maxlength="1500" placeholder="最近每周练几次；常练动作、工作重量×次数×组数；哪些动作熟悉、哪些要避开；恢复感受。">${esc(p.routine_detail||'')}</textarea><small>用于核对方案；缺少负荷基线时先校准，不凭空指定公斤数。</small></div><div class="form-field"><label for="usual-minutes">平时单次练多久（选填）</label><input id="usual-minutes" name="usual_minutes" type="number" min="10" max="240" value="${p.usual_minutes??''}" placeholder="分钟，如 35"><small>已规律运动时用这个时长确定起点；没形成规律可以留空。</small></div><div class="form-field"><label for="limitations">有需要特别留意的身体情况吗</label><textarea id="limitations" name="limitations" maxlength="1000" placeholder="近期不适、伤病或医生给出的限制；没有可以留空。">${esc(p.limitations)}</textarea><small>身体情况会作为注意事项纳入方案，请补充医生已明确的运动限制；一般风险不会阻止生成。</small></div><div class="form-field"><label for="profile-sex">界面偏好（选填）</label><select id="profile-sex" name="sex">${[['undisclosed','暂不设置'],['female','女性 · 显示经期调整入口'],['male','男性']].map(([id,label])=>`<option value="${id}" ${(p.sex||'undisclosed')===id?'selected':''}>${label}</option>`).join('')}</select><small>仅用于界面显示，不发送给模型；不会据此改变训练能力判断。</small></div><label class="check-row"><input type="checkbox" name="adult" ${p.adult?'checked':''} required>我已年满 18 周岁</label>`;else body=`<p class="intro">留一点真实可用的时间。选择你喜欢且能安全进行的项目；课程会按目标和运动基础分配训练与恢复。</p><div class="form-field"><label>哪些天比较有空（最多七天）</label><div class="chips">${dayNames.map((n,i)=>choice('days',i,n,p.days.includes(i))).join('')}</div></div><div class="form-grid"><div class="form-field"><label for="minutes">单次可用时间</label><input id="minutes" name="minutes" type="number" min="10" max="240" step="1" value="${p.minutes}" required><small>10–240 分钟；这是可用上限，实际安排会结合训练量和恢复。</small></div><div class="form-field"><label for="place">常用场地</label><select id="place" name="place">${[['gym','健身房'],['mixed','多个场地都可以'],['home','主要在家'],['outdoor','主要户外']].map(([id,n])=>`<option value="${id}" ${p.place===id?'selected':''}>${n}</option>`).join('')}</select></div></div><div class="form-field"><label>喜欢的运动方式</label><div class="chips">${Object.entries(activityNames).map(([id,n])=>choice('likes',id,n,p.likes.includes(id))).join('')}</div></div><div class="form-field"><label for="activity-detail">运动偏好与条件（选填）</label><textarea id="activity-detail" name="activity_detail" maxlength="1500" placeholder="其他运动项目、想避免的项目、同伴或场地条件，以及喜欢的训练方式。">${esc(p.activity_detail||'')}</textarea></div><div class="form-field"><label>手边的器械</label><div class="chips">${[['bodyweight','自重即可'],['dumbbell','哑铃'],['band','弹力带'],['treadmill','跑步机'],['stationary_bike','健身车'],['barbell','杠铃'],['rack','深蹲架'],['bench','训练凳'],['cable','绳索器械'],['machine','固定器械'],['pullup','单杠'],['kettlebell','壶铃'],['rower','划船机'],['ski_erg','滑雪机'],['sled','雪橇'],['medicine_ball','药球'],['box','跳箱'],['suspension','悬吊训练带'],['other','其他器械']].map(([id,n])=>choice('equipment',id,n,p.equipment.includes(id))).join('')}</div><small>只选实际可用且会安全使用的设备；没有对应器械时会考虑替代方案。</small></div><div class="form-field"><label for="equipment-detail">器械补充（选填）</label><textarea id="equipment-detail" name="equipment_detail" maxlength="1500" placeholder="哑铃重量范围、器械型号或条件，例如：可调哑铃2–24公斤、无训练凳。">${esc(p.equipment_detail||'')}</textarea></div><label class="check-row"><input type="checkbox" name="support_training" ${p.support_training!==false?'checked':''}>补充辅助训练（力量或增肌目标仍优先排抗阻）</label><label class="check-row"><input type="checkbox" name="consent" ${p.consent?'checked':''} required>同意保存必要运动档案和训练反馈，用于计划调整与周期跟进</label>`;showModal(['先说说，想改变什么','了解现在的你','给运动留一点空间'][onboardStep],`<div class="onboard-progress">${[0,1,2].map(i=>`<span class="${i<=onboardStep?'active':''}"></span>`).join('')}</div><form id="onboard-form">${body}<p id="onboard-error" class="error" role="alert"></p><div class="modal-foot">${onboardStep?'<button type="button" class="btn ghost" data-action="onboard-back">上一步</button>':''}<button type="submit" class="btn primary">${onboardStep===2?'保存档案并生成 AI 计划':'继续'} ${I('arrow')}</button></div></form>`)}
function collectOnboard(){const f=new FormData($('#onboard-form'));if(onboardStep===0){profileDraft.name=f.get('name')?.trim()||'运动者';profileDraft.goal=f.get('goal');profileDraft.planning_style=f.get('planning_style')||'adaptive';profileDraft.training_structure=f.get('training_structure')||'';profileDraft.motivation=f.get('motivation');profileDraft.goal_detail=f.get('goal_detail')||''}else if(onboardStep===1){profileDraft.current=f.get('current');profileDraft.training_background=f.get('training_background')||'';profileDraft.level=f.get('level');profileDraft.training_months=f.get('training_months')?Number(f.get('training_months')):null;profileDraft.routine_detail=f.get('routine_detail')||'';profileDraft.usual_minutes=f.get('usual_minutes')?Number(f.get('usual_minutes')):null;profileDraft.limitations=f.get('limitations');profileDraft.sex=f.get('sex')||'undisclosed';profileDraft.adult=f.has('adult')}else{profileDraft.days=f.getAll('days').map(Number);profileDraft.minutes=Number(f.get('minutes'));profileDraft.place=f.get('place');profileDraft.likes=f.getAll('likes');profileDraft.activity_detail=f.get('activity_detail')||'';profileDraft.equipment=f.getAll('equipment');profileDraft.equipment_detail=f.get('equipment_detail')||'';profileDraft.support_training=f.has('support_training');profileDraft.consent=f.has('consent')}}
function openCoach(session=null){chatSession=session||null;drawer.hidden=false;renderCoach();$('#chat-text')?.focus()}
function renderCoach(){drawer.innerHTML=`<div class="coach-head"><div class="avatar">${I('spark')}</div><div><strong>你的运动教练</strong><small>${chatSession?'正在商量这次训练':'了解你的目标，也记得你的反馈'}</small></div><button class="icon-btn" data-action="close-coach" aria-label="关闭教练">${I('close')}</button></div><div class="chat-list" id="chat-list">${state().chat.length?state().chat.map(m=>`<div class="message ${m.role==='user'?'user':'assistant'}">${esc(m.text)}</div>`).join(''):'<div class="message assistant">你好，我们可以聊聊现在的安排。时间、场地或感受有变化，告诉我就好。</div>'}${sending?`<div class="message user">${esc(pendingText)}</div><div class="message assistant">正在结合你的安排和反馈想一想…</div>`:''}${proposalId?`<div class="proposal-box"><strong>有一份待确认的调整</strong><p>先看看具体改变，再决定是否采用。</p><div class="actions"><button class="btn primary small" data-action="view-proposal" data-id="${proposalId}">查看调整 ${I('arrow')}</button></div></div>`:''}</div><form class="chat-compose" id="chat-form"><div class="chips"><button class="btn small ghost" type="button" data-action="quick-coach" data-text="今天只有十分钟">只有十分钟</button><button class="btn small ghost" type="button" data-action="quick-coach" data-text="这周轻一点">这周轻一点</button><button class="btn small ghost" type="button" data-action="quick-coach" data-text="今天想休息">今天想休息</button></div><div class="chat-input-row"><textarea id="chat-text" name="text" aria-label="发给教练的话" placeholder="比如：明天出差，想换成室内活动…" maxlength="1500" rows="2" required></textarea><button class="btn primary" type="submit" aria-label="发送">${I('send')}</button></div>${state().coach_plan_request?.trim()?`<button class="btn ghost small coach-plan-button" type="button" data-action="coach-plan" ${sending?'disabled':''}>按讨论生成草案 ${I('arrow')}</button>`:''}<div class="coach-mode">${data.capabilities.ai?'先讨论原因、取舍和替代；你决定后，再按讨论生成草案。':'基础教练模式 · 支持缩短、改期、室内替换、休息和重新开始。'}<br>重要变更会先给你预览，采用后才生效。</div></form>`;const list=$('#chat-list');list.scrollTop=list.scrollHeight}
function coachContextProposal(){if(!chatSession||previewAccountId!==data?.user?.id||!previewSessions.has(chatSession))return null;const adopted=[...(state().history||[]),state().plan,state().upcoming].filter(Boolean).some(plan=>plan.sessions.some(session=>session.id===chatSession));return adopted?null:previewProposalId}
async function sendChat(text){if(!text.trim()||sending)return;if(!state().profile){toast('先建立运动档案，教练才能了解你的安排');return}sending=true;pendingText=text;renderCoach();const form=$('#chat-form'),buttons=form?.querySelectorAll('button');buttons?.forEach(b=>b.disabled=true);const area=$('#chat-text');if(area)area.value='';try{const out=await mutate('/coach',{text,session_id:chatSession,...(coachContextProposal()?{proposal_id:coachContextProposal()}:{})});proposalId=out.result.proposal_id;if(out.result.can_plan&&out.result.plan_request)state().coach_plan_request=out.result.plan_request;renderCoach()}catch(e){toast(e.message);if(area)area.value=text}finally{sending=false;pendingText='';if(!drawer.hidden)renderCoach();buttons?.forEach(b=>b.disabled=false)}}
function planSources(plan){const sources=(plan.sources||plan.knowledge?.sources||[]).filter(x=>/^https:\/\//.test(x.url||''));return sources.length?`<details class="privacy-note"><summary>查看训练参考依据</summary><ul>${sources.map(x=>`<li><a href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.title)}</a></li>`).join('')}</ul><p>这些来源支持训练原则；具体动作、负荷与恢复仍以你的实际反馈校准。</p></details>`:''}
function planAssessment(plan){const q=plan.quality,trace=plan.review_trace||[];if(!q&&!trace.length)return '';return `<details class="privacy-note"><summary>查看计划评价依据${typeof q?.score==='number'?' · '+q.score+' 分':''}</summary>${q?`<p>${q.type==='independent_model_review'?'独立模型评价':'计划检查'} · ${esc(q.status||'已完成')}</p>${(q.limits||[]).map(x=>`<p>${esc(x)}</p>`).join('')}`:''}${trace.map(t=>`<div class="version-list"><strong>第 ${Number(t.round)+1} 轮 · ${esc(planningStage(t.stage||'评审'))}${typeof t.review?.score==='number'?' · '+t.review.score+' 分':''}</strong>${t.message?`<p>${esc(t.message)}</p>`:''}${t.changes?.length?`<p>${t.changes.map(x=>esc(x.date||'')+' '+esc(x.step||x.field||'')+'：'+esc(x.reason||'已按评审修正')).join('<br>')}</p>`:''}${t.review?.rationale?`<p>${esc(t.review.rationale)}</p>`:''}${[...(t.issues||[]),...(t.review?.issues||[])].map(x=>`<p>${esc(typeof x==='string'?x:(x.message||''))}${x.fix?'；建议：'+esc(x.fix):''}</p>`).join('')}${(t.review?.must_fix||[]).map(x=>`<p>需修正：${esc(x)}</p>`).join('')}${t.error?`<p>${esc(t.error)}</p>`:''}</div>`).join('')}</details>`}
async function viewProposal(id){const accountId=data?.user?.id;const draft=await api('/proposals/'+encodeURIComponent(id)),plan=draft.plan,old=new Map((state().plan?.sessions||[]).map(s=>[s.id,s]));if(data?.user?.id!==accountId)return;previewProposalId=id;previewAccountId=accountId;previewSessions=new Map(plan.sessions.map(s=>[s.id,s]));showModal('先看看，这样安排合适吗',`<p class="intro">${esc(draft.summary||plan.rationale)}</p>${plan.rationale&&draft.summary!==plan.rationale?`<p>${esc(plan.rationale)}</p>`:''}${plan.generator?.model?`<p class="small-text muted">生成模型：${esc(plan.generator.model)}${plan.generator.review_model?' · 独立复评：'+esc(plan.generator.review_model):''}</p>`:''}${plan.risk?.message?`<p class="privacy-note">${esc(plan.risk.message)}</p>`:''}${plan.assumptions?.length?`<details class="privacy-note" open><summary>这份计划采用的假设</summary><ul>${plan.assumptions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''}${plan.questions?.length?`<div class="privacy-note"><strong>仍需你确认</strong><ul>${plan.questions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><button class="text-btn" data-action="onboard">补充运动档案</button></div>`:''}${planAssessment(plan)}${planSources(plan)}<p class="privacy-note">采用前现有计划保留。采用后更新对应周的安排和提醒，过去的实际训练记录保留。</p>${plan.sessions.map(s=>{const before=old.get(s.id),diff=before&&(before.minutes!==s.minutes||before.date!==s.date||before.kind!==s.kind);return `<details class="card section"><summary><strong>${esc(s.title)}</strong><br><span class="small-text muted">${fmt(s.date,{month:'numeric',day:'numeric',weekday:'short'})} · ${s.minutes} 分钟${diff||s.customized?' · 已调整':''} · 点开看具体怎么练</span></summary><p>${esc(s.purpose)}</p><p><b>强度：</b>${esc(s.intensity)}</p>${s.focus?`<p><b>重点：</b>${esc(s.focus)}</p>`:''}${s.steps.map((x,i)=>workoutStep(s,x,i,false)).join('')}${s.recovery_note?`<p><b>恢复：</b>${esc(s.recovery_note)}</p>`:''}${diff?`<p class="small-text muted">原安排：${esc(before.title)} · ${before.minutes} 分钟</p>`:''}</details>`}).join('')}${plan.programming?`<details class="card section"><summary>查看周剂量、进阶与复盘安排</summary>${plan.programming.direct_sets?.length?`<p>动作标注肌群的工作组：${plan.programming.direct_sets.map(x=>esc(muscleName(x.muscle))+' '+esc(muscleDose(x))).join(' · ')}（力量与爆发分列，不等同增肌有效组）</p>`:''}<p>${esc(plan.programming.scope)}</p><p>${esc(plan.programming.progression)}</p><p>${esc(plan.programming.deload)}</p><p>${esc(plan.programming.review)}</p>${plan.programming.missing?.length?`<p>仍需核对：${plan.programming.missing.map(esc).join('；')}</p>`:''}</details>`:''}<p id="proposal-error" class="error" role="alert"></p><div class="modal-foot"><button class="btn ghost" data-action="close-modal">暂时不改</button><button class="btn primary" data-action="apply-proposal" data-id="${esc(id)}">采用这份安排 ${I('check')}</button></div>`)}
function feedback(id=null,recordId=null){const s=id?sessionBy(id):null,r=s?recordFor(s):state().records.find(x=>x.id===recordId),measured=!!(s&&timerSession===s.id&&timerStart),elapsed=measured?Date.now()-timerStart:0,suggestedStatus=measured&&elapsed<s.minutes*60000*.8?'partial':'completed';showModal(r?'编辑运动记录':s?'记录这次运动的感受':'记录一次自主活动',`<p class="intro">${s?esc(s.title)+' · '+fmt(s.date):'散步、打球、游泳，计划之外的活动也值得留下。'}<br>真实反馈比一张全绿的课表更有用。</p><form id="feedback-form" data-id="${s?.id||''}" data-record-id="${!s&&r?esc(r.id):''}">${!s?`<div class="form-field"><label for="activity">活动名称</label><input id="activity" name="activity" value="${esc(r?.activity||'')}" placeholder="比如：和朋友打羽毛球" maxlength="80" required></div><div class="form-field"><label for="activity-kind">运动类型</label><select id="activity-kind" name="activity_kind" required><option value="">选择类型，便于按项目比较负荷</option>${Object.entries(kindNames).filter(([k])=>k!=='rest').map(([k,v])=>`<option value="${k}" ${r?.activity_kind===k?'selected':''}>${v}</option>`).join('')}<option value="other" ${r&&(r.activity_kind==='other'||!r.activity_kind)?'selected':''}>其他</option></select></div><div class="form-field"><label for="record-date">活动日期</label><input id="record-date" type="date" name="date" value="${r?.date||data.today}" max="${data.today}" required></div>`:`<input type="hidden" name="date" value="${s.date}">`}<div class="form-field"><label>这次完成了多少</label><div class="chips">${[['completed','完整完成'],['partial','完成一部分'],['skipped','没能完成'],['rest','主动休息']].map(([v,n])=>choice('status',v,n,(r?.status||suggestedStatus)===v,'radio')).join('')}</div></div><div class="form-field"><label for="actual-minutes">实际活动时长（分钟）</label><input id="actual-minutes" type="number" name="minutes" value="${r?.minutes??(measured?Math.max(0,Math.round(elapsed/60000)):s?.minutes||'')}" min="0" max="300" required><small>按实际时长记录；不足 1 分钟的尝试可记 0 并选「完成一部分」。</small></div><div class="form-field"><label for="average-heart-rate">平均心率（次/分，选填）</label><input id="average-heart-rate" type="number" inputmode="numeric" name="avg_heart_rate" min="1" max="300" step="1" value="${r?.avg_heart_rate??''}" placeholder="例如 126"><small>可填手表或设备显示的本次运动平均值，没有测量可留空。</small></div><div class="form-field"><label>整体感觉怎么样</label><div class="chips">${[['easy','轻松，还有余力'],['okay','刚刚好'],['hard','有点吃力']].map(([v,n])=>choice('effort',v,n,(r?.effort||'okay')===v,'radio')).join('')}</div></div><label class="check-row"><input type="checkbox" name="pain" ${r?.pain?'checked':''}>运动时出现了疼痛或异常不适（用于调整长期安排）</label><div class="form-field"><label for="record-note">想留给自己或教练的话</label><textarea id="record-note" name="note" placeholder="比如：今天状态不错；或加班后有点累。" maxlength="1000">${esc(r?.note||'')}</textarea></div><p id="feedback-error" class="error" role="alert"></p><div class="modal-foot"><button class="btn ghost" type="button" data-action="close-modal">再想想</button><button class="btn primary" type="submit">保存这次记录 ${I('check')}</button></div></form>`)}
function training(id){const s=sessionBy(id);if(!s||s.kind==='rest')return;if(state().blocked){toast('请先确认年龄适用范围');return}if(s.date!==data.today){toast('只能开始今天的训练；想提前练可以先调整日期');return}if(timerSession!==id){timerStart=0;timerSession=id}showModal(s.title,`${state().risk?.message?`<p class="privacy-note">${esc(state().risk.message)}</p>`:''}<div class="train-timer"><div class="eyebrow" style="justify-content:center">A LITTLE TIME FOR YOURSELF</div><div class="timer-value" id="timer-value">00:00</div><div class="timer-label">预计 ${s.minutes} 分钟 · ${esc(s.intensity||'按体感调整')} · 随时可以停下</div><div class="actions" style="justify-content:center"><button class="btn primary" data-action="timer-start" data-id="${id}">${I('play')} 开始计时</button><button class="btn ghost" data-action="feedback" data-id="${id}">结束并记录</button></div></div><div id="current-step" class="privacy-note">先看看下面的安排，准备好再开始。计时只是辅助，不要求赶进度。</div>${s.steps.map((x,i)=>workoutStep(s,x,i,!!data.session_options?.[s.id]?.length&&!timerStart)).join('')}<p class="small-text muted">如有疼痛、头晕等异常不适，先停止并记录，不要为了完成计时继续。</p>`);if(timerStart)startTimer(id)}
function startTimer(id){if(!timerStart)timerStart=Date.now();if(timerInterval)clearInterval(timerInterval);const update=()=>{const s=sessionBy(id),seconds=Math.floor((Date.now()-timerStart)/1000),el=$('#timer-value');if(!el)return;el.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;let accumulated=0,active=s.steps.at(-1);for(const step of s.steps){accumulated+=step.minutes*60;if(seconds<accumulated){active=step;break}}$('#current-step').textContent=seconds>=s.minutes*60?'预计时间到了。可以按感受结束并记录，不会自动标记完成。':'现在可以：'+active.title+'。'+active.detail};update();timerInterval=setInterval(update,1000);const b=modal.querySelector('[data-action="timer-start"]');if(b){b.disabled=true;b.innerHTML=I('clock')+' 正在计时'}}
function adjust(id){chatSession=id;const session=sessionBy(id),queued=state().upcoming?.sessions.some(x=>x.id===id);showModal('这次安排，想怎么调整？',`<p class="intro">${esc(sessionBy(id)?.title||'这次训练')}<br>快捷选择也会先生成预览，由你决定是否采用。</p><div class="stack">${(data.session_options?.[session?.id]||[]).map(k=>`<button class="btn ghost" data-action="swap-kind" data-id="${id}" data-kind="${k}">换成${kindNames[k]} · 先预览</button>`).join('')}${queued?'':`<button class="btn ghost" data-action="adjust-short" data-id="${id}">${I('clock')} 今天只有 10 分钟</button><button class="btn ghost" data-action="adjust-indoor" data-id="${id}">${I('home')} 换成室内轻松活动</button><form id="move-form" data-id="${id}"><div class="form-field"><label for="move-date">改到另一天</label><div class="flex"><input id="move-date" name="date" type="date" min="${data.today}" required><button class="btn ghost" style="flex-shrink:0">预览改期</button></div></div></form><button class="btn ghost" data-action="adjust-rest" data-id="${id}">${I('leaf')} 这次改为休息</button>`}</div><p class="error" id="adjust-error" role="alert"></p>`)}
async function quickAdjust(text,id){closeModal();openCoach(id);await sendChat(text);if(proposalId)await viewProposal(proposalId)}
const needsAiPlanning=()=>state().plan?.source==='ai_reviewed'||['performance','race','sport','custom'].includes(state().profile?.goal)||state().profile?.level==='competitive';
async function nextWeek(){if(needsAiPlanning())return startPlanning();if(data.direction[0]==='consider'){showModal('下一步，可以小一点',`<p class="intro">${esc(data.direction[1])}</p><label class="check-row"><input id="recovered" type="checkbox">近期训练后恢复良好，没有异常不适</label><p class="small-text muted">可以先保持；如果选择进阶，单次最多增加 5 分钟，仍由你预览确认。</p><div class="modal-foot"><button class="btn ghost" data-action="next-draft">保持当前节奏</button><button class="btn primary" data-action="next-progress">确认恢复，预览进阶</button></div><p id="next-error" class="error" role="alert"></p>`)}else await nextDraft(false,false)}
async function nextDraft(progress,recovered){if(needsAiPlanning())return startPlanning();const out=await mutate('/plan/next',{progress,recovered});proposalId=out.result.proposal_id;await viewProposal(proposalId)}
function showNotices(){showModal('给你的提醒',`${data.notices.length?data.notices.map(n=>`<div class="version-list"><strong>${esc(n.title)}</strong><p>${esc(n.body)}</p><small class="muted">${esc(n.created_at)} UTC</small></div>`).join(''):'<div class="empty"><div class="empty-icon">'+I('bell')+'</div><p>暂时没有新提醒。<br>到你设置的时间，站内提醒会出现在这里。</p></div>'}<p class="small-text muted">站内提醒会保存；离线时只有已配置且开启的邮件可送达。<br>邮件状态：${data.deliveries.map(x=>({sent:'已发送',pending:'待发送',sending:'发送中',uncertain:'结果未确认',cancelled:'已取消'}[x.status]||x.status)+' '+x.count).join(' · ')||'暂无发送记录'}</p><div class="modal-foot"><button class="btn ghost" data-action="reminder-settings">调整提醒偏好 ${I('arrow')}</button></div>`);api('/notices/read','POST').then(()=>{data.notices.forEach(n=>n.read=1);render()}).catch(()=>{})}
async function action(name,el){switch(name){case 'demo':el.disabled=true;data=await api('/demo','POST');page='today';render();break;case 'new-demo':el.disabled=true;data=await api('/demo','POST',{mode:'empty'});proposalId=null;drawer.hidden=true;closeModal();page='today';render();if(!state().profile)startOnboard();else toast('你已登录正式账号，可以在「我的」修改计划');break;case 'privacy':showModal('数据与隐私',`<p class="intro">你的运动计划和身体反馈默认私密，只用于向你提供计划、调整与复盘。</p><div class="review-body"><strong>保存哪些内容</strong>登录邮箱、运动档案、计划与修改历史、训练反馈、对话、提醒偏好保存在服务器。你可以在「我的」导出或删除账号数据。<strong>什么时候发送给 AI</strong>点击「整理档案」、生成 AI 计划或向教练发送消息时，必要自述、训练档案与近期反馈会交给模型服务处理；经期按钮记录的状态和运动记录里的平均心率不会发送给 AI，也不会写进邮件。供应商的数据处理遵循其服务政策。<strong>提醒和邮件</strong>邮件默认只提醒你查看安排，不附身体情况；可以随时关闭或暂停。演示空间不发送邮件。<strong>删除和备份</strong>账号删除会清除在线账号及关联训练数据。服务器每日备份最多保留约 30 天，备份中的数据随保留周期到期清除。模型供应商的留存不由本站直接控制。</div><div class="modal-foot"><button class="btn primary" data-action="close-modal">知道了</button></div>`);break;case 'login':login();break;case 'account':accountMenu();break;case 'account-settings':closeModal();page='me';render();window.scrollTo({top:0,behavior:'smooth'});break;case 'close-modal':closeModal();break;case 'send-code':{const f=new FormData($('#login-form'));if(!$('#email').reportValidity())return;el.disabled=true;try{const out=await api('/auth/code','POST',{email:f.get('email'),invite:f.get('invite')});$('#login-info').textContent=out.dev_code?'本机开发验证码：'+out.dev_code+'（仅本机显示）':'验证码已发出，请查收邮箱';if(out.dev_code)$('#login-form [name="code"]').value=out.dev_code;el.textContent='60 秒后可重发';setTimeout(()=>{el.disabled=false;el.textContent='重新获取'},60000)}catch(e){el.disabled=false;$('#login-error').textContent=e.message}break}case 'period':if(state().profile?.sex==='female')showPeriod();break;case 'period-end':{el.disabled=true;try{const out=await mutate('/period',{},'DELETE');timerSession=null;timerStart=0;closeModal();toast(out.result)}catch(e){$('#period-error').textContent=e.message;el.disabled=false}break}case 'ai-plan':planningRequest();break;case 'ai-plan-submit':el.disabled=true;try{await startPlanning($('#planning-request')?.value||'')}finally{el.disabled=false}break;case 'planning-progress':if(planningJob?.status==='done'&&planningJob.proposal_id)await showPlanningResult();else planningModal();break;case 'planning-result':await showPlanningResult();break;case 'onboard':startOnboard();break;case 'intake':{const text=$('#intake-text').value;if(text.trim().length<3){$('#intake-info').textContent='先写几句你的现状和想法。';break}el.disabled=true;el.textContent='正在整理…';try{collectOnboard();const out=await api('/intake','POST',{text});Object.assign(profileDraft,out.patch);onboard();$('#intake-text').value=text;$('#intake-info').textContent=out.reply;toast(out.mode==='ai'?'AI 已整理，请逐项核对':'已整理明确的信息，请继续核对')}finally{el.disabled=false}break;}case 'onboard-back':collectOnboard();onboardStep--;onboard();break;case 'select-day':selected=el.dataset.id;page='plan';render();break;case 'movement-guide':showMovementGuide(el.dataset.id,Number(el.dataset.step));break;case 'guide-back':if(guideReturnTraining&&guideReturnSession)training(guideReturnSession);else if(guideReturnProposal)await viewProposal(guideReturnProposal);else closeModal();break;case 'ask-session-why':case 'ask-step-why':{const session=sessionBy(el.dataset.id);if(!session)break;const step=name==='ask-step-why'?session.steps?.[Number(el.dataset.step)]:null;closeModal();openCoach(session.id);await sendChat(`请先解释原因，与我讨论，不修改计划。课程ID：${session.id}；课程：${session.title}；日期：${session.date}。${step?'动作序号：'+(Number(el.dataset.step)+1)+'；动作：'+step.title+'。':''}为什么这样安排？它与我的目标和现有基础有什么关系，有什么取舍、替代与调整信号？`);break}case 'coach-plan':{const request=(state().coach_plan_request||'').trim();if(!request){toast('先与教练明确这次想调整什么，再生成草案。');break}drawer.hidden=true;await startPlanning(request,state().coach_plan_session_id||null,state().coach_plan_proposal_id||null);break}case 'coach':openCoach();break;case 'close-coach':drawer.hidden=true;break;case 'quick-coach':if(drawer.hidden)openCoach();await sendChat(el.dataset.text);break;case 'view-proposal':await viewProposal(el.dataset.id);break;case 'apply-proposal':{el.disabled=true;try{const out=await mutate('/proposals/'+el.dataset.id+'/apply');proposalId=null;planningJob=null;try{localStorage.removeItem(planningKey())}catch{}closeModal();if(state().upcoming){page='plan';selected=state().upcoming.sessions.find(s=>s.kind!=='rest')?.id||null}render();toast(out.result)}catch(e){$('#proposal-error').textContent=e.message;el.disabled=false}break}case 'training':training(el.dataset.id);break;case 'timer-start':startTimer(el.dataset.id);break;case 'feedback':feedback(el.dataset.id);break;case 'free-record':feedback();break;case 'edit-growth-record':{const r=state().records.find(r=>r.id===el.dataset.id);if(r)feedback(r.session_id,r.id);break}case 'growth-period':growthCadence=el.dataset.cadence;render();$('[data-action="growth-period"][aria-pressed="true"]')?.focus();break;case 'garden-plot':gardenPlot=el.dataset.kind;render();$('.garden-tile[aria-pressed="true"]')?.focus();break;case 'adjust':adjust(el.dataset.id);break;case 'swap-step':case 'swap-kind':{el.disabled=true;try{const payload=name==='swap-step'?{step_index:Number(el.dataset.step)}:{kind:el.dataset.kind};const out=await mutate('/plan/swap',{session_id:el.dataset.id,...payload});await viewProposal(out.result.proposal_id)}finally{el.disabled=false}break}case 'adjust-short':await quickAdjust('今天只有 10 分钟',el.dataset.id);break;case 'adjust-indoor':await quickAdjust('今天换成室内活动',el.dataset.id);break;case 'adjust-rest':await quickAdjust('今天想休息',el.dataset.id);break;case 'undo':{const out=await mutate('/plan/undo');toast(out.result);break}case 'review':{el.disabled=true;const out=await mutate('/reviews',{cadence:el.dataset.cadence});toast('已根据实际记录生成回顾');break}case 'next-week':await nextWeek();break;case 'next-draft':await nextDraft(false,false);break;case 'next-progress':if(!$('#recovered').checked){$('#next-error').textContent='请先确认近期恢复情况，或选择保持当前节奏。';return}await nextDraft(true,true);break;case 'notices':showNotices();break;case 'reminder-settings':closeModal();page='me';render();break;case 'learn':showModal('为什么不需要补欠课',`<p class="intro">计划服务于身体和生活。把漏掉的训练集中到后面，可能使活动突然增加，也会挤掉恢复时间。</p><p class="small-text muted">更好的下一步是记录没能完成的原因，保留适当恢复，重新安排后面的训练。暂时中断时，先从可接受的起点回来。</p><div class="privacy-note">本周完成情况会区分原始计划、调整后的安排和真实活动；不会通过删除训练把结果变成“全部完成”。</div><p class="sources">参考：<a href="https://www.niddk.nih.gov/health-information/weight-management/tips-get-active/tips-starting-physical-activity" target="_blank" rel="noopener">NIDDK · 从少量活动开始，逐步增加</a></p>`);break;case 'logout':await api('/auth/logout','POST');drawer.hidden=true;closeModal();proposalId=null;landing();break;case 'delete':showModal('删除这个空间里的数据',`<p class="intro">将删除账号、会话、个人档案、计划、训练记录和提醒。删除后无法恢复。可以先导出一份备份。</p><div class="actions"><a class="btn ghost" href="/api/export">先导出数据</a><button class="btn danger" data-action="delete-confirm">确认删除</button></div>`);break;case 'delete-confirm':await api('/account','DELETE');closeModal();drawer.hidden=true;landing();toast('账号与训练数据已删除');break}}
document.addEventListener('click',async e=>{const p=e.target.closest('[data-page]');if(p){page=p.dataset.page;render();window.scrollTo({top:0,behavior:'smooth'});return}const el=e.target.closest('[data-action]');if(el){try{await action(el.dataset.action,el)}catch(err){toast(err.message);el.disabled=false}}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,submit=form.querySelector('[type="submit"]'),fd=new FormData(form);if(submit)submit.disabled=true;try{if(form.id==='login-form'){data=await api('/auth/verify','POST',{...Object.fromEntries(fd),import_trial:fd.has('import_trial')});proposalId=null;drawer.hidden=true;closeModal();page='today';render();if(!state().profile)startOnboard()}else if(form.id==='onboard-form'){collectOnboard();if(onboardStep<2){onboardStep++;onboard()}else{if(!profileDraft.days.length||profileDraft.days.length>7)throw new Error('请选择 1–7 个可用训练日');if(!profileDraft.likes.length)throw new Error('至少选择一种喜欢的运动方式');const out=await mutate('/profile',{profile:profileDraft,ai_first:true},'PUT');closeModal();page=state().blocked?'me':'plan';render();if(state().blocked)toast(out.result);else await startPlanning()}}else if(form.id==='period-form'){const out=await mutate('/period',{mode:fd.get('mode'),days:Number(fd.get('days'))},'PUT');timerSession=null;timerStart=0;closeModal();toast(out.result)}else if(form.id==='feedback-form'){const status=fd.get('status');const out=await mutate('/records',{session_id:form.dataset.id||null,record_id:form.dataset.recordId||null,date:fd.get('date'),status,minutes:['rest','skipped'].includes(status)?0:Number(fd.get('minutes')),effort:fd.get('effort'),pain:fd.has('pain'),note:fd.get('note'),activity:fd.get('activity')||sessionBy(form.dataset.id)?.title||'自主活动',activity_kind:fd.get('activity_kind')||null,avg_heart_rate:!['rest','skipped'].includes(status)&&fd.get('avg_heart_rate')?Number(fd.get('avg_heart_rate')):null});closeModal();timerStart=0;timerSession=null;toast(out.result)}else if(form.id==='chat-form'){await sendChat(fd.get('text'))}else if(form.id==='move-form'){await quickAdjust('改到 '+fd.get('date'),form.dataset.id)}else if(form.id==='settings-form'){const obj=Object.fromEntries(fd);for(const n of ['daily','weekly','monthly','followup','email'])obj[n]=fd.has(n);const out=await mutate('/settings',obj,'PUT');toast(out.result)}}catch(err){const id={ 'login-form':'login-error','onboard-form':'onboard-error','feedback-form':'feedback-error','period-form':'period-error','settings-form':'settings-error','move-form':'adjust-error'}[form.id],el=id?$('#'+id):null;if(el)el.textContent=err.message;else toast(err.message)}finally{if(submit)submit.disabled=false}});
document.addEventListener('change',e=>{if(e.target.name==='status'&&$('#actual-minutes')&&['skipped','rest'].includes(e.target.value))$('#actual-minutes').value=0});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!drawer.hidden)drawer.hidden=true;if(e.target.id==='chat-text'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#chat-form').requestSubmit()}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
window.addEventListener('online',()=>toast('已重新连接，可以继续记录。'));
window.addEventListener('offline',()=>toast('当前离线，暂时无法同步。恢复连接后再保存记录。'));
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
load();
